const productOwnerRuns = `-- name: ProductOwnerRuns :many
SELECT r.operation_id, r.account_id, r.app_id, r.tenant_id, r.revision, r.feature, r.plan, r.currency, r.period, r.unit_price_millicents, r.admitted_at, r.succeeded_at, r.admission_evidence, r.resolved_state, r.resolved_at,w.reason AS waiver_reason,w.created_at AS waived_at,
 coalesce(CASE WHEN o.state IN ('accepted','running','waiting') OR o.expires_at > $5::timestamptz
  OR o.record->'data_repair'->>'phase' IN ('applying','outcome_unknown','replacing','resolving') THEN o.state END,'')::text AS state,
 (SELECT coalesce(-sum(d.amount_millicents),0)::bigint FROM product_control_billing_documents d
  WHERE d.operation_id=r.operation_id AND d.account_id=r.account_id AND d.app_id=r.app_id AND d.kind='credit_note') AS credited_millicents
FROM product_control_receipts r LEFT JOIN product_control_waivers w USING(operation_id)
LEFT JOIN customer_operations o ON o.id=r.operation_id AND o.account_id=r.account_id AND o.app_id=r.app_id AND o.platform_tenant_id=r.tenant_id
WHERE r.account_id=$1 AND r.app_id=$2 AND r.tenant_id=$3 AND r.period=$4
 AND (NOT $6::boolean OR (r.resolved_state='' AND w.operation_id IS NULL AND
  (r.period < $7::text OR o.id IS NULL OR o.state NOT IN ('accepted','running','waiting'))))
 AND ($8::text='' OR (r.admitted_at,r.operation_id) < ($9::timestamptz,$10::uuid))
ORDER BY r.admitted_at DESC,r.operation_id DESC LIMIT $11
`

