const verifyProductStripeInvoiceSend = `-- name: VerifyProductStripeInvoiceSend :execrows
UPDATE product_control_stripe_invoice_sends a
SET stage = 'sent', send_event_id = $1, send_event_at = $2
FROM usage_statement_invoice_exports e
WHERE a.export_id = e.id AND e.account_id = $3 AND e.id = $4
  AND e.claim_token = $5 AND e.claimed_until > now()
  AND a.stage = 'sending' AND a.send_started_at <= $6::timestamptz
  AND $2::timestamptz >= date_trunc('second', a.send_started_at)
`

type VerifyProductStripeInvoiceSendParams struct {
	EventID     pgtype.Text
	EventAt     pgtype.Timestamptz
	AccountID   pgtype.UUID
	ExportID    pgtype.UUID
	Token       pgtype.UUID
	RetryBefore pgtype.Timestamptz
}

func (q *Queries) VerifyProductStripeInvoiceSend(ctx context.Context, db DBTX, arg VerifyProductStripeInvoiceSendParams) (int64, error) {
	result, err := db.Exec(ctx, verifyProductStripeInvoiceSend,
		arg.EventID,
		arg.EventAt,
		arg.AccountID,
		arg.ExportID,
		arg.Token,
		arg.RetryBefore,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
